-- 14: PRE-FLIGHT for the Phase 2 module migrations 20261018100000 .. 20261018200000 (read-only; it was run on 18 Oct BEFORE they were applied and returned no rows).
-- It lists problems: a function or table name that already exists, or a prerequisite function, table or column that is missing. Rows = STOP.
-- AFTER the migrations are applied it will (correctly) list every name as already existing; use 13_postflight_phase2_modules.sql then.

select 'function already exists' as problem, p.proname as name from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname = any(array['owner_money','organizer_guests','organizer_guest_summary','agreement_detail','agreement_list','agreement_close','agreement_note','agreement_accept','agreement_propose','agreement_request','agreement_sample','agreement_check_terms','agreement_percent','agreement_side','change_member_role','vip_redeem','vip_lookup','vip_invite','vip_detail','vip_list','vip_end_perk','vip_add_perk','vip_reinstate','vip_end','vip_update','vip_add','vip_new_code','vip_date','vip_status','stock_movements','stock_set_threshold','stock_move','stock_list','night_report','reopen_night','close_night','night_close_status','night_check','night_checklist','night_report_data','night_blockers','night_booking_ids','night_checklist_items','security_summary','security_review_incident','security_incident_note','security_incident_detail','security_incidents','security_report_incident','security_task_act','security_tasks','security_create_task','security_alert_act','security_alerts','security_raise_alert','security_has_role','chat_purge_expired','chat_start_direct','chat_people','chat_pin','chat_mark_read','chat_send','chat_messages','chat_conversations','chat_user_at_venue','chat_can_access','desk_booking_messages','desk_booking_seating','desk_unseat','desk_set_estimate','desk_mark_seated','desk_find_booking','desk_enqueue','desk_verifier_summary','desk_list_flags','desk_resolve_flag','desk_flag_payment','desk_receive_handover','desk_list_handovers','desk_submit_handover','desk_cash_position','desk_cash_rows','desk_cash_part']::text[])
union all
select 'table already exists', c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname = any(array['site_agreement_notes','site_agreement_versions','site_agreements','site_vip_redemptions','site_vip_perks','site_vip_members','site_stock_thresholds','site_stock_movements','site_night_closes','site_night_checks','site_security_incident_notes','site_security_incidents','site_security_tasks','site_security_alerts','site_chat_reads','site_chat_messages','site_chat_direct_members','site_chat_conversations','site_outbox','site_booking_seating','site_payment_flags','site_cash_handovers']::text[])
union all
select 'MISSING prerequisite function', f from unnest(array['desk_log','desk_level','desk_booking_level','booking_night','booking_venue','can_access_venue','can_access_event','active_memberships','is_org_member','setup_text','setup_int','setup_only_keys','invite_member','can_invite_role','revoke_membership','create_shift','search_venues']) f
  where not exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=f)
union all
select 'MISSING prerequisite table', t from unnest(array['site_venues','site_events','site_organizations','site_memberships','site_shifts','site_table_bookings','site_table_types','site_venue_time_slots','site_table_booking_club_payments','site_table_booking_bottles','site_service_requests','site_booking_servers','site_bottles','site_orders','site_ticket_tiers','profiles','audit_log']) t
  where to_regclass('public.'||t) is null
union all
select 'MISSING prerequisite column', x from unnest(array['site_table_booking_club_payments.corrects_payment_id','site_table_booking_club_payments.manager_verified_at','site_table_booking_club_payments.customer_confirmation_status','site_table_booking_club_payments.receipt_photo_path','site_table_booking_club_payments.split_breakdown','site_table_booking_club_payments.recorded_by','site_table_booking_bottles.service_status','site_table_booking_bottles.payment_status','site_table_booking_bottles.cancelled_at','site_table_booking_bottles.line_total_cents','site_table_bookings.amount_paid_cents','site_table_bookings.discount_cents','site_table_bookings.confirmation_code','site_bottles.stock_quantity','site_bottles.is_sold_out','site_orders.checked_in_at','site_orders.ticket_code','site_orders.status','site_events.org_id','site_events.start_date','site_events.end_date','site_venues.org_id']) x
  where not exists (select 1 from information_schema.columns c where c.table_schema='public' and c.table_name=split_part(x,'.',1) and c.column_name=split_part(x,'.',2))
order by 1,2
